on conflict(provider_key) do update set display_name=excluded.display_name,provider_type=excluded.provider_type,lifecycle_status=excluded.lifecycle_status,direct_api_available=excluded.direct_api_available,capabilities=excluded.capabilities,notes=excluded.notes,verified_at=excluded.verified_at,updated_at=now();

update private.ai_providers set lifecycle_status='adapter_ready',updated_at=now() where provider_key='google' and lifecycle_status not in ('deprecated','removed');

on conflict(runtime_key) do update set adapter_key=excluded.adapter_key,enabled=excluded.enabled,credential_secret_names=excluded.credential_secret_names,configuration=excluded.configuration,updated_at=now();

on conflict(model_key) do update set provider_model_id=excluded.provider_model_id,display_name=excluded.display_name,family=excluded.family,lifecycle_status=excluded.lifecycle_status,input_modalities=excluded.input_modalities,output_modalities=excluded.output_modalities,route_tags=excluded.route_tags,capabilities=excluded.capabilities,cost_profile=excluded.cost_profile,deprecation_risk=excluded.deprecation_risk,updated_at=now();

update private.ai_route_policies set primary_models=array['cloudflare:nemotron-3-120b-a12b','groq:qwen3.8-27b']::text[],fallback_models=array['nvidia_nemotron_3_5_lightning','google:gemini-3.7-flash','openai:gpt-5.6-luna']::text[],max_attempts=5,optimization_objective='lowest_cost_passing_quality',notes='FREE-FIRST: Cloudflare/Groq before direct/premium providers. Quality validators still required.',updated_at=now() where task_type='conversation' and quality_tier='q1';
update private.ai_route_policies set primary_models=array['cloudflare:nemotron-3-120b-a12b','groq:gpt-oss-120b']::text[],fallback_models=array['nvidia_nemotron_3_5_lightning','google:gemini-3.7-flash','openai:gpt-5.6-terra']::text[],max_attempts=5,optimization_objective='lowest_cost_passing_quality',notes='FREE-FIRST balanced conversation route with premium escalation only after free candidates.',updated_at=now() where task_type='conversation' and quality_tier='q2';
update private.ai_route_policies set primary_models=array['cloudflare:nemotron-3-120b-a12b','groq:gpt-oss-120b']::text[],fallback_models=array['google:gemini-3.7-flash','nvidia_nemotron_3_5_lightning','openai:gpt-5.6-sol']::text[],max_attempts=5,optimization_objective='best_quality_within_ceiling',notes='QUALITY-FIRST while still trying strong free candidates before premium escalation.',updated_at=now() where task_type='conversation' and quality_tier='q3';
update private.ai_route_policies set primary_models=array['cloudflare:gemma-4-26b-a4b-it','cloudflare:nemotron-3-120b-a12b']::text[],fallback_models=array['groq:gpt-oss-120b','nvidia_nemotron_3_5_lightning','openai:gpt-5.6-luna']::text[],max_attempts=5,optimization_objective='lowest_cost_passing_quality',notes='FREE-FIRST property extraction; deterministic evidence validators remain authoritative.',updated_at=now() where task_type='property_extract' and quality_tier in ('q1','q2');
